fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the AI app via the application switcher dropdown next to the logo (NOT Ctrl+K), open the MCP section, then go to the Tools tab. Click the 'Test Tool' button in the header to open the 'Test MCP Tool' dialog. Confirm the dialog shows a three-step wizard with a step indicator reading '1. Select', '2. Configure', '3. Results', and that the Select step presents Server, Connection, and Tool selectors (with a tool search box). Seeing the multi-step Test Tool wizard render on the Select step is success — you do NOT need to pick a real tool or actually execute anything (there may be no servers/connections configured). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
